package org.mockito.internal.stubbing.defaultanswers;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.internal.InternalMockHandler;
import org.mockito.internal.bytecode.Mock;
import org.mockito.internal.creation.settings.CreationSettings;
import org.mockito.internal.stubbing.InvocationContainerImpl;
import org.mockito.internal.stubbing.StubbedInvocationMatcher;
import org.mockito.internal.stubbing.Stubbing;
import org.mockito.internal.util.MockCreationValidator;
import org.mockito.internal.util.MockUtil;
import org.mockito.internal.util.reflection.GenericMetadataSupport;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ReturnsDeepStubs_answer_TriageGen2Test {

    private ReturnsDeepStubs returnsDeepStubs;
    private InvocationOnMock invocation;
    private Stubbing delegate;
    private Object mockObject;

    // Subclass to allow overriding protected method actualParameterizedType for testing
    private static class TestableReturnsDeepStubs extends ReturnsDeepStubs {
        private GenericMetadataSupport metadata;

        public TestableReturnsDeepStubs(Stubbing delegate) {
            super(delegate);
        }

        public void setMetadata(GenericMetadataSupport metadata) {
            this.metadata = metadata;
        }

        @Override
        protected GenericMetadataSupport actualParameterizedType(Object mock) {
            return metadata;
        }

        // Mocking the internal getMock method behavior via a spy or similar is hard, 
        // so we assume the real class's getMock(invocation) will be called.
        // In a real Mockito environment, getMock is part of the class.
    }

    @Before
    public void setUp() throws Exception {
        delegate = mock(Stubbing.class);
        returnsDeepStubs = new TestableReturnsDeepStubs(delegate);
        invocation = mock(InvocationOnMock.class);
        mockObject = mock(Object.class);

        when(invocation.getMock()).thenReturn(mockObject);
    }

    /**
     * Test case where the return type is NOT mockable.
     * This covers the branch: if (!new MockCreationValidator().isTypeMockable(rawType))
     */
    @Test
    public void testAnswer_WhenTypeIsNotMockable() throws Throwable {
        // String is generally not mockable by MockCreationValidator
        Class<?> rawType = String.class;
        GenericMetadataSupport metadata = mock(GenericMetadataSupport.class);
        when(metadata.rawType()).thenReturn(rawType);

        returnsDeepStubs.setMetadata(metadata);

        Method method = String.class.getMethod("length");
        when(invocation.getMethod()).thenReturn(method);

        Object expectedReturn = "fallback";
        when(delegate.returnValueFor(rawType)).thenReturn(expectedReturn);

        Object result = returnsDeepStubs.answer(invocation);

        assertEquals(expectedReturn, result);
    }

    /**
     * Test case where the return type IS mockable.
     * This covers the branch: return getMock(invocation);
     */
    @Test
    public void testAnswer_WhenTypeIsMockable() throws Throwable {
        // An interface is mockable
        Class<?> rawType = Runnable.class;
        GenericMetadataSupport metadata = mock(GenericMetadataSupport.class);
        when(metadata.rawType()).thenReturn(rawType);

        returnsDeepStubs.setMetadata(metadata);

        Method method = Runnable.class.getMethod("run");
        when(invocation.getMethod()).thenReturn(method);

        // Since we cannot easily mock the protected getMock(invocation) call inside the real class 
        // without PowerMock, and the prompt asks to test the provided method logic,
        // we rely on the fact that if it's mockable, it attempts to return a mock.
        // In a real integration test, getMock would return a new mock.
        // Here, we'll verify the logic flow. 
        // Note: In actual Mockito, getMock(invocation) is a protected method.

        // To strictly follow the instruction of testing the logic provided:
        // If we use the real class, getMock will be called. 
        // Because we can't easily mock 'getMock' without extra tools, we ensure the metadata path is hit.

        // We use a Spy to control getMock if possible, but since it's a protected method 
        // in the same class, we can override it in our Testable subclass.

        TestableReturnsDeepStubs spyStubbing = new TestableReturnsDeepStubs(delegate) {
            @Override
            protected Object getMock(InvocationOnMock invocation) {
                return "mocked_object";
            }
        };
        spyStubbing.setMetadata(metadata);

        Object result = spyStubbing.answer(invocation);

        assertEquals("mocked_object", result);
    }

    /**
     * Helper class to override getMock for the purpose of the test
     */
    private static class TestableReturnsDeepStubsWithMock extends ReturnsDeepStubs {
        private GenericMetadataSupport metadata;
        private Object mockToReturn;

        public TestableReturnsDeepStubsWithMock(Stubbing delegate) {
            super(delegate);
        }

        public void setMetadata(GenericMetadataSupport metadata) {
            this.metadata = metadata;
        }

        public void setMockToReturn(Object mockToReturn) {
            this.mockToReturn = mockToReturn;
        }

        @Override
        protected GenericMetadataSupport actualParameterizedType(Object mock) {
            return metadata;
        }

        @Override
        protected Object getMock(InvocationOnMock invocation) {
            return mockToReturn;
        }
    }
}
